 if(tab==="orders") c.innerHTML=`<section class="admin-form"><h3>Send an event reminder email</h3><p class="muted">Send a reminder to each buyer with a payment-confirmed ticket for the selected event. Pending and cancelled orders are excluded.</p><form id="eventReminderForm" class="stack"><label>Choose event *<select name="event_id" required><option value="">Select an event</option>${d.events.map(ev=>{const count=new Set(d.orders.filter(o=>Number(o.event_id)===Number(ev.id)&&["Paid","Used"].includes(o.status)).map(o=>String(o.buyer_email||"").toLowerCase()).filter(Boolean)).size;return `<option value="${ev.id}">${esc(ev.title)} — ${count} paid buyer(s)</option>`;}).join("")}</select></label><label>Email subject *<input name="subject" required maxlength="180" value="Reminder: upcoming ELCSA Mavhola Parish event"></label><label>Reminder message *<textarea name="message" rows="5" required maxlength="5000" placeholder="Write the reminder message for ticket buyers…"></textarea></label><button class="btn navy" id="sendEventReminder" type="submit">Send reminder to ticket buyers</button><p class="muted" id="eventReminderResult" role="status"></p></form></section><section class="admin-form ticket-scanner-panel"><h3>Scan tickets at the entrance</h3><p class="muted">Use your phone camera to scan the QR code on each paid ticket. First scan admits the guest; repeat scans are rejected.</p><div id="ticketReader" class="ticket-reader"></div><div class="decision-row"><button class="btn navy" id="startTicketScanner" type="button">Open phone camera</button><button class="action" id="stopTicketScanner" type="button" disabled>Stop camera</button></div><p id="ticketCheckInResult" class="ticket-scan-result" role="status" aria-live="assertive">Camera scanner ready.</p><details><summary>Enter ticket code manually</summary><form id="ticketCheckIn" class="stack"><label class="wide">Ticket QR token or verification link<input name="token" autocomplete="off" required></label><button class="btn navy">Check in ticket</button></form></details></section><h3>Ticket orders (${d.orders.length})</h3><p class="muted">Review orders and update their status when payment or cancellation has been confirmed.</p><table class="admin-table"><tr><th>Event</th><th>Buyer</th><th>Order / Ticket number</th><th>Tickets</th><th>Total</th><th>Status</th><th>Actions</th></tr>${d.orders.map(o=>`<tr><td>${esc(o.event_title)}</td><td><strong>${esc(o.buyer_name)}</strong><br>${esc(o.buyer_email)}</td><td><strong>${esc(o.ticket_numbers||"Not issued yet")}</strong><br><small>Order number / EFT reference: ${esc(o.order_reference||("MAV-"+String(o.id).padStart(6,"0")))}</small>${o.ticket_numbers?"":'<br><small class="muted">Ticket number assigned after payment is verified.</small>'}</td><td>${o.quantity}</td><td>${money(o.total_cents)}</td><td>${esc(o.status)}</td><td>${o.status==="Used"?'<span class="status used">All tickets scanned</span>':`<select id="orderStatus${o.id}"><option ${o.status==="Pending"?"selected":""}>Pending</option><option ${o.status==="Paid"?"selected":""}>Paid</option><option ${o.status==="Cancelled"?"selected":""}>Cancelled</option></select><button class="action" onclick="updateOrder(${o.id})">Save</button>`}${o.ticket_numbers?`<button class="action" type="button" data-resend-ticket-order="${o.id}">Resend ticket</button>`:""}<button class="action reject" type="button" data-delete-ticket-order="${o.id}">Delete tickets</button></td></tr>`).join("")}</table>`;
   const reminderForm=$("#eventReminderForm");if(reminderForm)reminderForm.onsubmit=async e=>{e.preventDefault();const form=e.target,button=$("#sendEventReminder"),status=$("#eventReminderResult"),data=new FormData(form);if(!confirm("Send this event reminder to all buyers with paid tickets for this event?"))return;button.disabled=true;button.textContent="Sending emails…";status.textContent="Sending individual reminder emails. Please keep this page open.";try{const sent=await api("/api/admin/events/"+encodeURIComponent(data.get("event_id"))+"/ticket-reminders",{method:"POST",body:JSON.stringify({subject:data.get("subject").trim(),message:data.get("message").trim()})});status.textContent="Reminder complete: "+sent.sent+" email(s) sent"+(sent.failed?", "+sent.failed+" failed":"")+". Recipients: "+sent.total+".";toast("Event reminder emails processed.");}catch(err){status.textContent=err.message||"Could not send event reminders.";toast(status.textContent);}finally{button.disabled=false;button.textContent="Send reminder to ticket buyers";}};
   const result=$("#ticketCheckInResult");
   const checkTicket=async raw=>{
    const value=String(raw||"").trim(),match=value.match(/([a-f0-9]{48})(?:\/?(?:\?.*)?)?$/i),token=match?match[1]:value;
    if(!token){result.textContent="Please scan a ticket QR code.";return;}
    result.className="ticket-scan-result checking";result.textContent="Checking ticket…";
    try{const data=await api("/api/admin/tickets/check-in",{method:"POST",body:JSON.stringify({token})});result.className="ticket-scan-result admitted";result.textContent="✓ ADMITTED — "+data.ticketNumber+" · First scan accepted.";const form=$("#ticketCheckIn");if(form)form.reset();}
    catch(err){const duplicate=/already been used/i.test(err.message);result.className="ticket-scan-result "+(duplicate?"duplicate":"rejected");result.textContent=duplicate?"⚠ ALREADY SCANNED — This ticket has already been used.":"✕ NOT ADMITTED — "+err.message;}
   };
   const checkForm=$("#ticketCheckIn");if(checkForm)checkForm.onsubmit=async e=>{e.preventDefault();await checkTicket(new FormData(checkForm).get("token"));};
   let ticketScanner=null;
   const startScannerButton=$("#startTicketScanner");if(startScannerButton)startScannerButton.onclick=async()=>{const start=$("#startTicketScanner"),stop=$("#stopTicketScanner");if(!window.Html5Qrcode){result.textContent="Scanner library did not load. Use manual entry.";return;}start.disabled=true;result.className="ticket-scan-result checking";result.textContent="Requesting camera permission…";try{ticketScanner=new Html5Qrcode("ticketReader");await ticketScanner.start({facingMode:"environment"},{fps:10,qrbox:{width:240,height:240},aspectRatio:1},async decoded=>{await ticketScanner.pause(true);await checkTicket(decoded);setTimeout(()=>{if(ticketScanner&&!stop.disabled)ticketScanner.resume();},2400);},()=>{});stop.disabled=false;result.textContent="Camera is on. Point it at a ticket QR code.";}catch(err){ticketScanner=null;result.className="ticket-scan-result rejected";result.textContent="Could not open camera. Allow camera access in your phone browser and try again.";}finally{start.disabled=false;}};
   const stopScannerButton=$("#stopTicketScanner");if(stopScannerButton)stopScannerButton.onclick=async()=>{if(ticketScanner){try{await ticketScanner.stop();ticketScanner.clear();}catch{}ticketScanner=null;}$("#stopTicketScanner").disabled=true;result.textContent="Camera stopped.";};
