window.editAnnouncement=async id=>{try{const d=await api("/api/admin/dashboard"),a=d.announcements.find(x=>x.id===id);if(!a)return;const title=prompt("Announcement title:",a.title);if(title===null)return;const body=prompt("Announcement text:",a.body);if(body===null)return;const pinned=confirm("Pin this as an important notice? Click OK for yes, Cancel for no.");await api(`/api/admin/announcements/${id}`,{method:"PUT",body:JSON.stringify({title,body,pinned})});toast("Announcement updated");showAdmin("announcements");loadPublic();}catch(e){toast(e.message)}};
