window.deleteTicketOrder=async id=>{if(!confirm("Permanently delete this ticket order and every ticket/QR code issued for it? This cannot be undone."))return;try{const result=await api(`/api/admin/orders/${id}`,{method:"DELETE"});toast(`Deleted ticket order and ${Number(result.deletedTicketCount||0)} issued ticket(s)`);showAdmin("orders");}catch(e){toast("Could not delete ticket order: "+e.message)}};

// Resend existing issued ticket PDFs to the buyer without creating new tickets or resetting QR check-in status.
document.addEventListener("click",async event=>{
 const button=event.target instanceof Element?event.target.closest("[data-resend-ticket-order]"):null;
 if(!button)return;
 event.preventDefault();event.stopPropagation();
 if(button.disabled)return;
 const id=button.getAttribute("data-resend-ticket-order");
 if(!id||!window.confirm("Resend the existing ticket PDF(s) to this buyer's email address? The ticket numbers and QR codes will remain unchanged."))return;
 button.disabled=true;const label=button.textContent;button.textContent="Sending…";
 try{
  const result=await api("/api/admin/orders/"+encodeURIComponent(id)+"/resend-tickets",{method:"POST"});
  toast("Ticket(s) resent to "+result.buyerEmail+". Existing ticket numbers and QR codes were kept.");
 }catch(error){toast("Could not resend ticket: "+(error&&error.message?error.message:String(error)));}
 finally{button.disabled=false;button.textContent=label;}
},true);

// One persistent delegated click handler: admin order rows are recreated on each
// dashboard render, so their controls must not depend on per-render listeners or inline JS.
document.addEventListener("click",async event=>{
 const button=event.target instanceof Element?event.target.closest("[data-delete-ticket-order]"):null;
 if(!button)return;
 event.preventDefault();
 event.stopPropagation();
 if(button.disabled)return;
 const id=button.getAttribute("data-delete-ticket-order");
 if(!id)return;
 if(!window.confirm("Permanently delete this ticket order and every ticket/QR code issued for it? This cannot be undone."))return;
 button.disabled=true;
 const label=button.textContent;
 button.textContent="Deleting…";
 try{
  const result=await api("/api/admin/orders/"+encodeURIComponent(id),{method:"DELETE"});
  toast("Deleted ticket order and "+Number(result.deletedTicketCount||0)+" issued ticket(s).");
  await showAdmin("orders");
 }catch(error){
  toast("Delete failed: "+(error&&error.message?error.message:String(error)));
  button.disabled=false;
  button.textContent=label;
 }
},true);


// Parish shop: category filters, product details, persistent cart and staged checkout.
 let shopProducts=[],shopCart=[],shopCategory="All products";
 const shopMoney=c=>"R "+(Number(c||0)/100).toFixed(2);
 function shopTotal(){return shopCart.reduce((n,x)=>n+Number(x.product.price_cents)*x.quantity,0)}
 function shopSave(){try{localStorage.setItem("mavholaShopCart",JSON.stringify(shopCart.map(x=>({id:x.product.id,q:x.quantity,s:x.size,c:x.color}))))}catch{}}
 function shopRestore(){try{shopCart=JSON.parse(localStorage.getItem("mavholaShopCart")||"[]").map(x=>{const p=shopProducts.find(y=>Number(y.id)===Number(x.id));return p?{product:p,quantity:Math.max(1,Math.min(20,Number(x.q)||1)),size:x.s||"",color:x.c||""}:null}).filter(Boolean)}catch{shopCart=[]}}
 function shopCategories(){return ["All products",...new Set(shopProducts.map(p=>String(p.category||"Merchandise").trim()))]}
 function renderShopFilters(){const el=$("#shopCategoryFilters");if(!el)return;el.innerHTML=shopCategories().map(c=>'<button class="shop-category-chip '+(c===shopCategory?"active":"")+'" data-category="'+esc(c)+'">'+esc(c)+'</button>').join("");el.querySelectorAll("[data-category]").forEach(b=>b.onclick=()=>{shopCategory=b.dataset.category;renderShopFilters();renderShopProducts()})}
 function shopOptions(p){return '<div class="shop-product-options">'+(p.sizes?.length?'<label>Size<select data-size>'+p.sizes.map(x=>'<option>'+esc(x)+'</option>').join("")+'</select></label>':'')+(p.colors?.length?'<label>Colour<select data-color>'+p.colors.map(x=>'<option>'+esc(x)+'</option>').join("")+'</select></label>':'')+'<label>Quantity<input data-qty type="number" min="1" max="20" value="1"></label></div>'}
 function shopAdd(p,s="",c="",q=1){const item=shopCart.find(x=>Number(x.product.id)===Number(p.id)&&x.size===s&&x.color===c);if(item)item.quantity=Math.min(20,item.quantity+q);else shopCart.push({product:p,size:s,color:c,quantity:q});shopSave();renderShopCart();toast(p.title+" added to cart")}
 function shopDetail(id){const p=shopProducts.find(x=>Number(x.id)===Number(id));if(!p)return;const el=$("#shopProductDetail");el.innerHTML='<div class="shop-detail-layout">'+(p.image_url?'<img class="shop-detail-image" src="'+p.image_url+'" alt="'+esc(p.title)+'">':'<div class="shop-product-placeholder shop-detail-image">ELCSA MAVHOLA PARISH</div>')+'<div class="shop-detail-copy"><span class="shop-category">'+esc(p.category||"Merchandise")+'</span><h2>'+esc(p.title)+'</h2><strong class="shop-price">'+shopMoney(p.price_cents)+'</strong><p>'+esc(p.description||"Parish shop merchandise.")+'</p><p class="shop-stock">'+(p.stock_quantity===null?"Available to order":p.stock_quantity===0?"Out of stock":p.stock_quantity+" available")+'</p>'+shopOptions(p)+'<button class="btn navy shop-detail-add" data-detail-add '+(p.stock_quantity===0?"disabled":"")+'>Add to cart</button></div></div>';open("shopProductModal");el.querySelector("[data-detail-add]").onclick=()=>{shopAdd(p,el.querySelector("[data-size]")?.value||"",el.querySelector("[data-color]")?.value||"",Math.max(1,Math.min(20,Number(el.querySelector("[data-qty]")?.value)||1)));close("shopProductModal")}}
 function renderShopProducts(){const root=$("#shopProducts"),term=($("#shopSearch")?.value||"").trim().toLowerCase();const items=shopProducts.filter(p=>(shopCategory==="All products"||String(p.category||"Merchandise").trim()===shopCategory)&&(!term||[p.title,p.category,p.description].some(v=>String(v||"").toLowerCase().includes(term))));if(!items.length){root.innerHTML='<div class="shop-empty"><h3>No products found</h3><p>Try another category or search.</p></div>';return}root.innerHTML=items.map(p=>'<article class="shop-product">'+(p.image_url?'<button class="shop-product-image-button" data-detail="'+p.id+'"><img class="shop-product-image" loading="lazy" src="'+p.image_url+'" alt="'+esc(p.title)+'"></button>':'<button class="shop-product-image-button" data-detail="'+p.id+'"><div class="shop-product-placeholder">ELCSA MAVHOLA PARISH</div></button>')+'<div class="shop-product-body"><span class="shop-category">'+esc(p.category||"Merchandise")+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.description||"")+'</p><strong class="shop-price">'+shopMoney(p.price_cents)+'</strong><div class="shop-card-actions"><button class="btn shop-view-button" data-detail="'+p.id+'">View details</button><button class="btn navy" data-quick="'+p.id+'" '+ (p.stock_quantity===0?"disabled":"")+'>Add to cart</button></div></div></article>').join("");root.querySelectorAll("[data-detail]").forEach(b=>b.onclick=()=>shopDetail(Number(b.dataset.detail)));root.querySelectorAll("[data-quick]").forEach(b=>b.onclick=()=>{const p=shopProducts.find(x=>Number(x.id)===Number(b.dataset.quick));if(p)shopAdd(p,p.sizes?.[0]||"",p.colors?.[0]||"",1)})}
 function renderShopCart(){const count=shopCart.reduce((n,x)=>n+x.quantity,0);$("#shopCartCount").textContent=count;$("#shopCartTotal").textContent=shopMoney(shopTotal());shopSave()}
 function showShopFlow(step){const root=$("#shopFlowContent");if(step==="cart"){root.innerHTML='<span class="eyebrow">YOUR BAG</span><h1 class="shop-flow-title">Shopping cart</h1><p class="shop-flow-subtitle">Review your items before continuing.</p><div id="shopCartLines"></div><div class="shop-flow-buttons"><button class="btn shop-view-button" id="shopContinue">Continue shopping</button><button class="btn navy" id="shopCheckoutNext" '+(shopCart.length?"":"disabled")+'>Continue to checkout</button></div>';renderCartLines();$("#shopContinue").onclick=()=>close("shopCartModal");$("#shopCheckoutNext").onclick=()=>showShopFlow("checkout");return}
 if(step==="checkout"){root.innerHTML='<span class="eyebrow">SECURE CHECKOUT</span><h1 class="shop-flow-title">Checkout</h1><div class="shop-checkout-grid"><form id="shopCheckoutForm" class="shop-checkout-form"><h2>Customer details</h2><label>Full name *<input name="customer_name" required maxlength="120"></label><label>Email address *<input name="customer_email" type="email" required></label><label>Phone number<input name="customer_phone" type="tel"></label><h2>Payment method</h2><label class="shop-payment-choice"><input type="radio" name="payment_method" value="eft" checked><span><b>EFT payment</b><small>Upload proof of payment</small></span></label><label class="shop-payment-choice"><input type="radio" name="payment_method" value="card" '+($("#shopCardOption")?.disabled?"disabled":"")+'><span><b>Online card payment</b><small>Secure PayFast checkout</small></span></label><label class="shop-proof-field" id="shopProofField">EFT proof of payment *<input name="proof_of_payment" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,application/pdf,image/jpeg,image/png,image/webp"><small>PDF or image, maximum 10 MB.</small></label><p id="shopCheckoutMessage" class="message" role="status"></p><div class="shop-flow-buttons"><button type="button" class="btn shop-view-button" id="shopBack">Back to cart</button><button type="submit" class="btn navy" id="shopPlaceOrder">Place order</button></div></form><aside class="shop-order-summary"><h2>Order summary</h2><div id="shopCheckoutSummary"></div></aside></div>';renderSummary();$("#shopBack").onclick=()=>showShopFlow("cart");const form=$("#shopCheckoutForm");form.querySelectorAll('input[name="payment_method"]').forEach(r=>r.onchange=()=>{$("#shopProofField").hidden=form.elements.payment_method.value!=="eft"});form.onsubmit=async e=>{e.preventDefault();const method=form.elements.payment_method.value,msg=$("#shopCheckoutMessage"),btn=$("#shopPlaceOrder");if(method==="eft"&&!form.elements.proof_of_payment.files.length){msg.textContent="Please upload your EFT proof of payment.";return}btn.disabled=true;msg.textContent="Submitting your order…";try{const data=new FormData(form);data.set("cart",JSON.stringify(shopCart.map(x=>({product_id:x.product.id,quantity:x.quantity,size:x.size,color:x.color}))));const result=await api("/api/shop/checkout",{method:"POST",body:data});if(method==="card"){const f=document.createElement("form");f.method="POST";f.action=result.paymentUrl;f.style.display="none";Object.entries(result.fields).forEach(([k,v])=>{const i=document.createElement("input");i.type="hidden";i.name=k;i.value=v;f.appendChild(i)});document.body.appendChild(f);f.submit();return}shopCart=[];localStorage.removeItem("mavholaShopCart");renderShopCart();root.innerHTML='<div class="shop-order-confirmation"><div class="shop-confirmation-icon">✓</div><span class="eyebrow">ORDER RECEIVED</span><h1>Thank you!</h1><p>'+esc(result.message)+'</p><div class="shop-confirmation-reference"><small>ORDER REFERENCE</small><strong>'+esc(result.orderReference)+'</strong></div><p>We will email your confirmation. The parish will verify your EFT payment and update your order.</p><button class="btn navy" id="shopFinish">Continue shopping</button></div>';$("#shopFinish").onclick=()=>close("shopCartModal")}catch(err){msg.textContent=err.message;btn.disabled=false}};return}
 }
 function renderCartLines(){const el=$("#shopCartLines");if(!shopCart.length){el.innerHTML='<div class="shop-empty"><h3>Your cart is empty</h3><p>Browse the shop to add products.</p></div>';return}el.innerHTML=shopCart.map((x,i)=>'<div class="shop-cart-line"><div class="shop-cart-product">'+(x.product.image_url?'<img src="'+x.product.image_url+'" alt="">':'')+'<div><b>'+esc(x.product.title)+'</b><small>'+esc([x.size,x.color].filter(Boolean).join(" · "))+' · '+shopMoney(x.product.price_cents)+' each</small><strong>'+shopMoney(x.product.price_cents*x.quantity)+'</strong></div></div><div class="shop-cart-qty"><button data-minus="'+i+'">−</button><span>'+x.quantity+'</span><button data-plus="'+i+'">+</button><button data-remove="'+i+'">Remove</button></div></div>').join("")+'<div class="shop-cart-total"><span>Subtotal</span><b>'+shopMoney(shopTotal())+'</b></div>';el.querySelectorAll("[data-minus]").forEach(b=>b.onclick=()=>{const i=Number(b.dataset.minus);if(--shopCart[i].quantity<1)shopCart.splice(i,1);renderShopCart();showShopFlow("cart")});el.querySelectorAll("[data-plus]").forEach(b=>b.onclick=()=>{const i=Number(b.dataset.plus);shopCart[i].quantity=Math.min(20,shopCart[i].quantity+1);renderShopCart();showShopFlow("cart")});el.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{shopCart.splice(Number(b.dataset.remove),1);renderShopCart();showShopFlow("cart")})}
 function renderSummary(){const el=$("#shopCheckoutSummary");el.innerHTML=shopCart.map(x=>'<div class="shop-summary-line"><span>'+esc(x.product.title)+' × '+x.quantity+'</span><b>'+shopMoney(x.product.price_cents*x.quantity)+'</b></div>').join("")+'<div class="shop-cart-total"><span>Subtotal</span><b>'+shopMoney(shopTotal())+'</b></div>'}
 async function loadShop(){try{const d=await api("/api/shop/products");shopProducts=d.products||[];const card=$("#shopCardOption");if(card)card.disabled=!d.cardPaymentsEnabled;$("#shopPaymentNotice").textContent=d.cardPaymentsEnabled?"Secure checkout · EFT or card":"EFT payment available · Card payments are being prepared";shopRestore();renderShopFilters();renderShopProducts();renderShopCart();$("#shopSearch").oninput=renderShopProducts;const status=new URLSearchParams(location.search).get("shopPayment");if(status)$("#shopMessage").textContent=status==="success"?"Payment submitted; awaiting secure confirmation.":"Payment cancelled. Your cart is still available."}catch(e){$("#shopProducts").innerHTML='<div class="shop-empty"><h3>Shop temporarily unavailable</h3><p>Please try again later.</p></div>';console.error(e)}}
 $("#openShopCart").onclick=()=>{renderShopCart();showShopFlow("cart");open("shopCartModal")};loadShop();renderShopCart();
 window.removeShopProduct=async id=>{if(!confirm("Remove this product from the public shop? Existing order history will be kept."))return;try{await api("/api/shop/admin/products/"+id,{method:"DELETE"});toast("Product removed");showAdmin("shop");loadShop();}catch(e){toast(e.message);}};
window.updateShopOrder=async(id,status)=>{try{const d=await api("/api/shop/admin/orders/"+id,{method:"PUT",body:JSON.stringify({status})});toast(status==="Paid"?(d.emailSent?"Payment confirmed and buyer emailed.":"Payment confirmed; buyer email could not be sent."):"Order cancelled.");showAdmin("shop");}catch(e){toast(e.message);}};
const shopParams=new URLSearchParams(location.search);if(shopParams.has("shopPayment")){const n=$("#shopMessage");if(n)n.textContent=shopParams.get("shopPayment")==="success"?"Thank you. PayFast is processing your payment confirmation; the order will update when the secure payment notification is verified.":"Payment was cancelled. Your cart is still available if you wish to try again.";}
loadShop();renderShopCart();
 // Dedicated section views: Shop and Youth League open independently.
